{"source":"import sys
import csv
import json
from decimal import Decimal, ROUND_HALF_UP


def fmt(d):
    return str(d.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))


def main():
    if len(sys.argv) < 2:
        print(json.dumps({"categories": [], "total": "0.00"}))
        return

    filepath = sys.argv[1]

    categories = {}
    total_sum = Decimal('0.00')

    with open(filepath, 'r', encoding='utf-8', newline='') as f:
        reader = csv.reader(f)
        header = next(reader, None)
        if header is None:
            print(json.dumps({"categories": [], "total": "0.00"}))
            return

        cat_idx = header.index('category')
        amt_idx = header.index('amount')
        stat_idx = header.index('status')

        for row in reader:
            if len(row) <= max(cat_idx, amt_idx, stat_idx):
                continue
            category = row[cat_idx] if len(row) > cat_idx else ''
            amount_str = row[amt_idx] if len(row) > amt_idx else ''
            status = row[stat_idx] if len(row) > stat_idx else ''

            if status.strip().casefold() != 'paid':
                continue

            cat_normalized = ' '.join(category.split()).casefold()
            if cat_normalized == '':
                cat_normalized = 'uncategorized'

            amount = Decimal(amount_str)
            amount_rounded = amount.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

            if cat_normalized not in categories:
                categories[cat_normalized] = Decimal('0.00')
            categories[cat_normalized] += amount_rounded
            total_sum += amount_rounded

    sorted_cats = sorted(categories.keys())
    result_categories = [
        {"category": c, "total": fmt(categories[c])}
        for c in sorted_cats
    ]

    result = {"categories": result_categories, "total": fmt(total_sum)}
    print(json.dumps(result))


if __name__ == '__main__':
    main()"}

